Mock algoliasearch client is lacking the cache object:
```
import { SearchQuery } from 'algoliasearch/lite';

const requestsCache = new Map<string, Promise<Response>>();
const resultsCache = new Map<string, any>();

function makeCacheKey(requests: SearchQuery[]) {
  // You can go further here, like sorting individual values inside the requests
  // to make sure the key is always the same for the same requests.
  // We're keeping it simple here for the sake of the example.
  return JSON.stringify(requests);
}

export async function search(requests: SearchQuery[]) {
  try {
    const key = makeCacheKey(requests);
    if (resultsCache.has(key)) {
      return resultsCache.get(key);
    }
    let request;
    if (requestsCache.has(key)) {
      request = requestsCache.get(key)!;
    } else {
      request = fetch(`http://localhost:3001/api/search`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ requests }),
      });
      requestsCache.set(key, request);
    }
    const response = await request;

    if (!response.ok) {
      throw new Error(`HTTP error! Status: ${response.status} `);
    }

    const results = await response.json();

    if (!results || !Array.isArray(results.results)) {
      console.error('Unexpected response format:', results);
      return { results: [] };
    }

    resultsCache.set(key, results);

    return results;
  } catch (error) {
    console.error('Error fetching search results:', error);
    return { results: [] };
  }
}

export const searchClient = {
  search,
  clearCache() {
    requestsCache.clear();
    resultsCache.clear();
  },
};
```
